    @Test
    @DisplayName("A page that does not exist answers 404 (/suite-builder-no-such-page-c8e8c6b9)")
    void aPageThatDoesNotExistIsNotFound() {
        APIResponse response = context.request().get(SiteConfig.url("/suite-builder-no-such-page-c8e8c6b9"));
        // A site that answers anything to an address that cannot exist is filed as a bug (bugs/open/SITE-05.md): while
        // it is open, this test is blocked by it.
        if (KnownBugs.open("SITE-05") && response.status() != 404) throw KnownBugs.blocked("SITE-05",
                "/suite-builder-no-such-page-c8e8c6b9 answered " + response.status()
                + ", not 404: missing pages look like pages");
        if (KnownBugs.open("SITE-05")) KnownBugs.looksFixed("SITE-05",
                "/suite-builder-no-such-page-c8e8c6b9 answers 404");
        assertTrue(response.status() == 404, "/suite-builder-no-such-page-c8e8c6b9 answered " + response.status()
                + ", not 404: a page that does not exist should say so");
    }
